<script>
   $(document).ready(function () {

       $(".js-popup-screen_bonus").click(function (e) {

           e.preventDefault();
           $("body").addClass("open-frame");
           $(".popup-frame").css("display", "flex").hide().fadeIn();
           $(".stock-screen-bonus").fadeIn();
       });


     // TODO: Акция Пригласите друга - нажатие на кнопку скопировать код
       $(".copy-row").click(function (e) {
           e.preventDefault();
           var copied_text = $('#friend_email').attr('code');

           if (navigator.clipboard && navigator.clipboard.writeText) {
               navigator.clipboard.writeText(copied_text)
                   .then(function() {
                       console.log("Text copied to clipboard successfully.");
                   })
                   .catch(function(error) {
                       console.error("Unable to write to clipboard:", error);
                   });
           } else {
               var tempInput = $('<input>');
               $('body').append(tempInput);
               tempInput.val(copied_text).select();
               try {
                   var successful = document.execCommand('copy');
                   var msg = successful ? "Text copied to clipboard successfully." : "Unable to copy to clipboard.";
                   console.log(msg);
               } catch (error) {
                   console.error("Unable to copy to clipboard:", error);
               }
               tempInput.remove();
           }
       });




/// TODO: Facebook Нажатие на кнопку отправить
       $(".submit_facebook").click(function (e) {
           e.preventDefault();
           $('.js_facebook_sale').submit();
       });


