       $(".js-popup-activation").click(function (e) {
           e.preventDefault();

           var user_id = $(this).attr('user_id');
           var coloumn= $(this).attr('coloumn');

           $.ajax({
               processData: false,
               contentType: false,
               type: 'POST',
               headers: {
                   'X-CSRF-TOKEN': $('meta[name="csrf-token"]').attr('content')
               },
               url: '/stocks/create_coupon',
               data: JSON.stringify({
                   'user_id': user_id,
                   'coloumn': coloumn
               }),
               success: function (response) {
                   if (response) {
                       if (response.message == 'Error') {
                           $("body").addClass("open-frame");
                           $(".popup-frame").css("display", "flex").hide().fadeIn();
                           $(".stock-a-js-error").fadeIn();
                       }

                       if (response.message == 'Success') {
                           $("body").addClass("open-frame");
                           $(".popup-frame").css("display", "flex").hide().fadeIn();
                           $(".stock-a-js").fadeIn();
                       }

                   }
               },
               error: function (error) {
                   cur_btn.removeAttr('disabled');
                   $('.js_spinner').removeClass('spinner');
                   console.log(error);
               }
           });







       });


        // TODO: Facebook Отправка формы, отправка скриншота facebook
        $(document).on('submit', '.js_facebook_sale', function (e) {
          //  alert("Сработал submit формы");
            e.preventDefault();
            var $input = $("#js_print_sale");
            var form_data = new FormData;
            var screen = $("#js_print_sale_screen").val()
            form_data.append('image', $input.prop('files')[0]);
            form_data.append('screen', screen);


            //$('.js_spinner').addClass('spinner');

            var cur_btn = $(this).find('button');
            cur_btn.attr('disabled', true);

            $.ajax({
                processData: false,
                contentType: false,
                type: 'POST',
                headers: {
                    'X-CSRF-TOKEN': $('meta[name="csrf-token"]').attr('content')
                },
                url: '/user/send_screen/',
                data: form_data,
                success: function (response) {
                    cur_btn.removeAttr('disabled');
                    $('.js_spinner').removeClass('spinner');
                    if (response) {
                        if (response.message == 'Invalid filesize or extension.') {
                            var msg = $('body').data('err_file');
                            alert(msg);
                        }

                        if (response.message ==
                            'The image must be a file of type: png, bmp, jpg, jpeg, heic, heif.') {
                            var msg = $('body').data('err_file');
                            alert(msg);
                        }

                        if (response.message == 'Success') {

                            $(".stock-screen-input").fadeOut(0);
                            $(".popup-frame").css("display", "flex").hide().fadeIn();
                            $(".stock-screen-js").fadeIn();


                        }
                    }
                },
